// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.ArrayList;
import java.util.BitSet;
import java.util.List;

import org.eclipse.rdf4j.common.annotation.Experimental;

/**
 * Kernel intermediate representation (plan: plans/lmdb-native-engine/19-kernel-ir-primitives.md). An IR tree describes
 * a whole-stage query pipeline as a composition of primitive operations; {@link LmdbNativeKernelEmitter} turns any
 * well-formed tree into one generated Java class implementing the {@code JaninoKernel} SPI. The IR is pure shape: node
 * fields are integers and booleans referencing positions in the runtime {@code KernelContext} (adjacency views,
 * constants, entry slots, key domains), never engine objects — which makes the canonical {@link Kernel#shapeKey()}
 * directly usable as the codegen cache key.
 *
 * Conventions: ids are dictionary-encoded longs compared unsigned; {@link #NULL_ID} (-1) is the unbound sentinel.
 * Columns are the generated kernel's working registers ({@code v0..vK} fields). A pipeline is a list of nodes executed
 * as nested loops in order, ending in a terminal ({@link Emit} or {@link Aggregate}); container nodes (exists, union)
 * hold sub-pipelines.
 */
@Experimental
final class LmdbNativeKernelIr {

	static final long NULL_ID = -1L;

	// Comparison operators shared by HAVING.
	static final int OP_EQ = 0;
	static final int OP_NE = 1;
	static final int OP_LT = 2;
	static final int OP_LE = 3;
	static final int OP_GT = 4;
	static final int OP_GE = 5;

	private LmdbNativeKernelIr() {
	}

	// ------------------------------------------------------------------
	// Operands
	// ------------------------------------------------------------------

	/** A value reference: a query constant, an entry-bound slot snapshot, or a pipeline column. */
	static final class Operand {
		static final int CONST = 0;
		static final int ENTRY = 1;
		static final int COL = 2;

		final int kind;
		final int index;

		private Operand(int kind, int index) {
			if (index < 0) {
				throw new IllegalArgumentException("operand index must be non-negative: " + index);
			}
			this.kind = kind;
			this.index = index;
		}

		static Operand constant(int index) {
			return new Operand(CONST, index);
		}

		static Operand entry(int index) {
			return new Operand(ENTRY, index);
		}

		static Operand col(int index) {
			return new Operand(COL, index);
		}

		/** Token used both in the canonical shape key and as the generated-source expression. */
		String token() {
			switch (kind) {
			case CONST:
				return "c" + index;
			case ENTRY:
				return "e" + index;
			default:
				return "v" + index;
			}
		}
	}

	// ------------------------------------------------------------------
	// Nodes
	// ------------------------------------------------------------------

	abstract static class Node {

		/** Appends this node's canonical rendering to the shape key. */
		abstract void key(StringBuilder key);

		/** Marks the columns this node (re)writes. */
		void produced(BitSet columns) {
		}

		/** Folds resource references (adjacency/constant/entry/domain indices) into the kernel's requirements. */
		abstract void requirements(Requirements requirements);
	}

	/** Aggregated resource-index maxima used by the emitter to declare fields. */
	static final class Requirements {
		int adjacencies;
		int constants;
		int entries;
		int domains;
		boolean hooks;

		void adjacency(int index) {
			adjacencies = Math.max(adjacencies, index + 1);
		}

		void operand(Operand operand) {
			if (operand.kind == Operand.CONST) {
				constants = Math.max(constants, operand.index + 1);
			} else if (operand.kind == Operand.ENTRY) {
				entries = Math.max(entries, operand.index + 1);
			}
		}

		void constantIndex(int index) {
			constants = Math.max(constants, index + 1);
		}

		void domain(int index) {
			domains = Math.max(domains, index + 1);
		}
	}

	/** Enumerate the key domain of a CSR view; optionally also expand each key's neighbor run in the same loop. */
	static final class EnumerateAdjKeys extends Node {
		final int adjacency;
		final int keyCol;
		final int valueCol; // -1 = keys only

		EnumerateAdjKeys(int adjacency, int keyCol, int valueCol) {
			this.adjacency = adjacency;
			this.keyCol = keyCol;
			this.valueCol = valueCol;
		}

		@Override
		void key(StringBuilder key) {
			key.append("EA(a").append(adjacency).append(",k").append(keyCol).append(",x").append(valueCol).append(");");
		}

		@Override
		void produced(BitSet columns) {
			columns.set(keyCol);
			if (valueCol >= 0) {
				columns.set(valueCol);
			}
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.adjacency(adjacency);
		}
	}

	/** Enumerate a pre-collected key array from {@code context.keyDomains} (VALUES lists, subquery results). */
	static final class EnumerateDomain extends Node {
		final int domain;
		final int col;

		EnumerateDomain(int domain, int col) {
			this.domain = domain;
			this.col = col;
		}

		@Override
		void key(StringBuilder key) {
			key.append("ED(d").append(domain).append(",k").append(col).append(");");
		}

		@Override
		void produced(BitSet columns) {
			columns.set(col);
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.domain(domain);
		}
	}

	/** Seed exactly one row from the enclosing entry bindings (the correlated/nested-invocation form). */
	static final class EnumerateEntry extends Node {

		@Override
		void key(StringBuilder key) {
			key.append("EE;");
		}

		@Override
		void requirements(Requirements requirements) {
		}
	}

	/** Expand: look a key up in a CSR view and loop its neighbor run into a fresh column. NULL keys match nothing. */
	static final class Probe extends Node {
		final int adjacency;
		final Operand key;
		final int valueCol;

		Probe(int adjacency, Operand key, int valueCol) {
			this.adjacency = adjacency;
			this.key = key;
			this.valueCol = valueCol;
		}

		@Override
		void key(StringBuilder key) {
			key.append("P(a")
					.append(adjacency)
					.append(',')
					.append(this.key.token())
					.append("->")
					.append(valueCol)
					.append(");");
		}

		@Override
		void produced(BitSet columns) {
			columns.set(valueCol);
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.adjacency(adjacency);
			requirements.operand(key);
		}
	}

	/**
	 * Both endpoints known: count matching entries in the key's run and re-emit the continuation that many times
	 * (multiplicity), or exactly once when any match exists (semi).
	 */
	static final class ProbeClose extends Node {
		final int adjacency;
		final Operand key;
		final Operand target;
		final boolean multiplicity;

		ProbeClose(int adjacency, Operand key, Operand target, boolean multiplicity) {
			this.adjacency = adjacency;
			this.key = key;
			this.target = target;
			this.multiplicity = multiplicity;
		}

		@Override
		void key(StringBuilder key) {
			key.append("C(a")
					.append(adjacency)
					.append(',')
					.append(this.key.token())
					.append(',')
					.append(target.token())
					.append(multiplicity ? ",m" : ",s")
					.append(");");
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.adjacency(adjacency);
			requirements.operand(key);
			requirements.operand(target);
		}
	}

	/**
	 * Sorted k-way intersection (the worst-case-optimal building block): emits each id present in every key's neighbor
	 * run, in unsigned order, with set semantics (duplicates within a run collapse).
	 */
	static final class Intersect extends Node {
		final int[] adjacencies;
		final Operand[] keys;
		final int valueCol;

		Intersect(int[] adjacencies, Operand[] keys, int valueCol) {
			if (adjacencies.length != keys.length || adjacencies.length < 2) {
				throw new IllegalArgumentException("intersect needs matching adjacency/key arrays of length >= 2");
			}
			this.adjacencies = adjacencies;
			this.keys = keys;
			this.valueCol = valueCol;
		}

		@Override
		void key(StringBuilder key) {
			key.append("I(");
			for (int i = 0; i < adjacencies.length; i++) {
				key.append(i == 0 ? "" : ",").append('a').append(adjacencies[i]).append(':').append(keys[i].token());
			}
			key.append("->").append(valueCol).append(");");
		}

		@Override
		void produced(BitSet columns) {
			columns.set(valueCol);
		}

		@Override
		void requirements(Requirements requirements) {
			for (int i = 0; i < adjacencies.length; i++) {
				requirements.adjacency(adjacencies[i]);
				requirements.operand(keys[i]);
			}
		}
	}

	/** Id-decidable equality/inequality guard. */
	static final class FilterCompareId extends Node {
		final boolean negated; // false = require equal, true = require not equal
		final Operand left;
		final Operand right;

		FilterCompareId(boolean negated, Operand left, Operand right) {
			this.negated = negated;
			this.left = left;
			this.right = right;
		}

		@Override
		void key(StringBuilder key) {
			key.append(negated ? "ne(" : "eq(").append(left.token()).append(',').append(right.token()).append(");");
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.operand(left);
			requirements.operand(right);
		}
	}

	/** Id membership in a set of query constants. */
	static final class FilterInConstants extends Node {
		final Operand value;
		final int[] constantIndices;

		FilterInConstants(Operand value, int[] constantIndices) {
			if (constantIndices.length == 0) {
				throw new IllegalArgumentException("IN filter needs at least one constant");
			}
			this.value = value;
			this.constantIndices = constantIndices;
		}

		@Override
		void key(StringBuilder key) {
			key.append("in(").append(value.token());
			for (int index : constantIndices) {
				key.append(",c").append(index);
			}
			key.append(");");
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.operand(value);
			for (int index : constantIndices) {
				requirements.constantIndex(index);
			}
		}
	}

	/** Inclusive unsigned id range guard (soundness of range-on-ids is the lowering's obligation). */
	static final class FilterRangeUnsigned extends Node {
		final Operand value;
		final int lowConstant;
		final int highConstant;

		FilterRangeUnsigned(Operand value, int lowConstant, int highConstant) {
			this.value = value;
			this.lowConstant = lowConstant;
			this.highConstant = highConstant;
		}

		@Override
		void key(StringBuilder key) {
			key.append("rg(")
					.append(value.token())
					.append(",c")
					.append(lowConstant)
					.append(",c")
					.append(highConstant)
					.append(");");
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.operand(value);
			requirements.constantIndex(lowConstant);
			requirements.constantIndex(highConstant);
		}
	}

	/** Value-tier guard: delegates to {@code hooks.testFilter} with up to three argument ids. */
	static final class FilterValue extends Node {
		final int filterId;
		final Operand[] args;

		FilterValue(int filterId, Operand[] args) {
			if (args.length > 3) {
				throw new IllegalArgumentException("value filters take at most 3 arguments");
			}
			this.filterId = filterId;
			this.args = args;
		}

		@Override
		void key(StringBuilder key) {
			key.append("fv(").append(filterId);
			for (Operand arg : args) {
				key.append(',').append(arg.token());
			}
			key.append(");");
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.hooks = true;
			for (Operand arg : args) {
				requirements.operand(arg);
			}
		}
	}

	/**
	 * OPTIONAL: like {@link Probe}, but when the key is NULL or has no matches the continuation runs exactly once with
	 * the value column set to NULL.
	 */
	static final class LeftProbe extends Node {
		final int adjacency;
		final Operand key;
		final int valueCol;

		LeftProbe(int adjacency, Operand key, int valueCol) {
			this.adjacency = adjacency;
			this.key = key;
			this.valueCol = valueCol;
		}

		@Override
		void key(StringBuilder key) {
			key.append("L(a")
					.append(adjacency)
					.append(',')
					.append(this.key.token())
					.append("->")
					.append(valueCol)
					.append(");");
		}

		@Override
		void produced(BitSet columns) {
			columns.set(valueCol);
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.adjacency(adjacency);
			requirements.operand(key);
		}
	}

	/**
	 * Existence witness: a sub-pipeline compiled to a boolean method that short-circuits on its first complete row.
	 * Guards the continuation on found (EXISTS) or not-found (NOT EXISTS / MINUS after lowering). Columns written
	 * inside the sub-pipeline are scratch: they must not be read by later outer nodes.
	 */
	static final class Exists extends Node {
		final boolean negated;
		final List<Node> pipeline;

		Exists(boolean negated, List<Node> pipeline) {
			if (pipeline.isEmpty()) {
				throw new IllegalArgumentException("exists sub-pipeline must not be empty");
			}
			this.negated = negated;
			this.pipeline = List.copyOf(pipeline);
		}

		@Override
		void key(StringBuilder key) {
			key.append(negated ? "nx{" : "ex{");
			for (Node node : pipeline) {
				node.key(key);
			}
			key.append("};");
		}

		@Override
		void requirements(Requirements requirements) {
			for (Node node : pipeline) {
				node.requirements(requirements);
			}
		}
	}

	/**
	 * UNION: branches run sequentially, each followed by the shared continuation. Every column produced by any branch
	 * is reset to NULL before each branch so bindings cannot leak across branches.
	 */
	static final class Union extends Node {
		final List<List<Node>> branches;

		Union(List<List<Node>> branches) {
			if (branches.size() < 2) {
				throw new IllegalArgumentException("union needs at least two branches");
			}
			List<List<Node>> copy = new ArrayList<>(branches.size());
			for (List<Node> branch : branches) {
				if (branch.isEmpty()) {
					throw new IllegalArgumentException("union branches must not be empty");
				}
				copy.add(List.copyOf(branch));
			}
			this.branches = List.copyOf(copy);
		}

		int[] resetColumns() {
			BitSet columns = new BitSet();
			for (List<Node> branch : branches) {
				for (Node node : branch) {
					node.produced(columns);
				}
			}
			int[] result = new int[columns.cardinality()];
			int out = 0;
			for (int col = columns.nextSetBit(0); col >= 0; col = columns.nextSetBit(col + 1)) {
				result[out++] = col;
			}
			return result;
		}

		@Override
		void key(StringBuilder key) {
			key.append("u{");
			for (List<Node> branch : branches) {
				key.append('[');
				for (Node node : branch) {
					node.key(key);
				}
				key.append(']');
			}
			key.append("};");
		}

		@Override
		void produced(BitSet columns) {
			for (List<Node> branch : branches) {
				for (Node node : branch) {
					node.produced(columns);
				}
			}
		}

		@Override
		void requirements(Requirements requirements) {
			for (List<Node> branch : branches) {
				for (Node node : branch) {
					node.requirements(requirements);
				}
			}
		}
	}

	/** BIND alias: copy an operand into a column. */
	static final class BindAlias extends Node {
		final Operand source;
		final int dstCol;

		BindAlias(Operand source, int dstCol) {
			this.source = source;
			this.dstCol = dstCol;
		}

		@Override
		void key(StringBuilder key) {
			key.append("ba(").append(source.token()).append("->").append(dstCol).append(");");
		}

		@Override
		void produced(BitSet columns) {
			columns.set(dstCol);
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.operand(source);
		}
	}

	/** Computed BIND via {@code hooks.computeBind}; NULL result means the expression errored (row survives). */
	static final class BindHook extends Node {
		final int bindId;
		final Operand[] args;
		final int dstCol;

		BindHook(int bindId, Operand[] args, int dstCol) {
			if (args.length > 2) {
				throw new IllegalArgumentException("bind hooks take at most 2 arguments");
			}
			this.bindId = bindId;
			this.args = args;
			this.dstCol = dstCol;
		}

		@Override
		void key(StringBuilder key) {
			key.append("bh(").append(bindId);
			for (Operand arg : args) {
				key.append(',').append(arg.token());
			}
			key.append("->").append(dstCol).append(");");
		}

		@Override
		void produced(BitSet columns) {
			columns.set(dstCol);
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.hooks = true;
			for (Operand arg : args) {
				requirements.operand(arg);
			}
		}
	}

	/**
	 * Arbitrary-length property path ({@code +} with minHops 1, {@code *} with minHops 0): breadth-first expansion over
	 * one CSR view with a visited set; each reachable node is emitted exactly once (SPARQL path set semantics).
	 * Fixed-length paths are not a primitive — they lower to {@link Probe} chains.
	 */
	static final class PathExpand extends Node {
		final int adjacency;
		final Operand source;
		final int dstCol;
		final int minHops; // 0 or 1

		PathExpand(int adjacency, Operand source, int dstCol, int minHops) {
			if (minHops != 0 && minHops != 1) {
				throw new IllegalArgumentException("minHops must be 0 (*) or 1 (+): " + minHops);
			}
			this.adjacency = adjacency;
			this.source = source;
			this.dstCol = dstCol;
			this.minHops = minHops;
		}

		@Override
		void key(StringBuilder key) {
			key.append("px(a")
					.append(adjacency)
					.append(',')
					.append(source.token())
					.append("->")
					.append(dstCol)
					.append(",h")
					.append(minHops)
					.append(");");
		}

		@Override
		void produced(BitSet columns) {
			columns.set(dstCol);
		}

		@Override
		void requirements(Requirements requirements) {
			requirements.adjacency(adjacency);
			requirements.operand(source);
		}
	}

	// ------------------------------------------------------------------
	// Terminals
	// ------------------------------------------------------------------

	/** Ordering/limit/offset modifiers shared by both terminals. */
	static final class OutputMods {
		final int[] orderKeys; // indexes into the OUTPUT row, null = no ordering
		final boolean[] descending; // null = all ascending
		final boolean valueOrder; // true = order via hooks.compareValues, false = unsigned id order
		final long limit; // -1 = none
		final long offset; // 0 = none

		OutputMods(int[] orderKeys, boolean[] descending, boolean valueOrder, long limit, long offset) {
			if (orderKeys != null && descending != null && orderKeys.length != descending.length) {
				throw new IllegalArgumentException("descending flags must match order keys");
			}
			if (offset < 0) {
				throw new IllegalArgumentException("offset must be non-negative");
			}
			this.orderKeys = orderKeys;
			this.descending = descending;
			this.valueOrder = valueOrder;
			this.limit = limit;
			this.offset = offset;
		}

		static OutputMods none() {
			return new OutputMods(null, null, false, -1L, 0L);
		}

		void key(StringBuilder key) {
			if (orderKeys != null) {
				key.append("ord(");
				for (int i = 0; i < orderKeys.length; i++) {
					key.append(i == 0 ? "" : ",")
							.append(orderKeys[i])
							.append(descending != null && descending[i] ? "d" : "a");
				}
				key.append(valueOrder ? ",val" : ",id").append(");");
			}
			if (limit >= 0 || offset > 0) {
				key.append("lim(").append(limit).append(',').append(offset).append(");");
			}
		}
	}

	abstract static class Terminal {
		final OutputMods mods;

		Terminal(OutputMods mods) {
			this.mods = mods;
		}

		abstract int stride();

		abstract void key(StringBuilder key);

		abstract void requirements(Requirements requirements);
	}

	/** Projects columns as the result row; optionally DISTINCT (the Dedup primitive). */
	static final class Emit extends Terminal {
		final int[] cols;
		final boolean distinct;

		Emit(int[] cols, boolean distinct, OutputMods mods) {
			super(mods);
			if (cols.length == 0) {
				throw new IllegalArgumentException("emit needs at least one column");
			}
			this.cols = cols;
			this.distinct = distinct;
		}

		Emit distinct() {
			return new Emit(cols, true, mods);
		}

		Emit withMods(OutputMods mods) {
			return new Emit(cols, distinct, mods);
		}

		@Override
		int stride() {
			return cols.length;
		}

		@Override
		void key(StringBuilder key) {
			key.append("emit(");
			for (int i = 0; i < cols.length; i++) {
				key.append(i == 0 ? "" : ",").append(cols[i]);
			}
			key.append(distinct ? ",distinct" : "").append(");");
			mods.key(key);
		}

		@Override
		void requirements(Requirements requirements) {
			if (mods.orderKeys != null && mods.valueOrder) {
				requirements.hooks = true;
			}
		}
	}

	// Aggregate function kinds.
	static final int AGG_COUNT_STAR = 0;
	static final int AGG_COUNT = 1;
	static final int AGG_COUNT_DISTINCT = 2;
	static final int AGG_SUM = 3;
	static final int AGG_MIN = 4;
	static final int AGG_MAX = 5;
	static final int AGG_AVG = 6;
	static final int AGG_MIN_ID = 7;
	static final int AGG_MAX_ID = 8;

	/** One projected aggregate. Count kinds emit plain longs; numeric kinds emit {@code Double.doubleToLongBits}. */
	static final class AggregateOutput {
		final int kind;
		final int col; // -1 for COUNT_STAR

		private AggregateOutput(int kind, int col) {
			this.kind = kind;
			this.col = col;
		}

		static AggregateOutput countStar() {
			return new AggregateOutput(AGG_COUNT_STAR, -1);
		}

		static AggregateOutput count(int col) {
			return new AggregateOutput(AGG_COUNT, col);
		}

		static AggregateOutput countDistinct(int col) {
			return new AggregateOutput(AGG_COUNT_DISTINCT, col);
		}

		static AggregateOutput sum(int col) {
			return new AggregateOutput(AGG_SUM, col);
		}

		static AggregateOutput min(int col) {
			return new AggregateOutput(AGG_MIN, col);
		}

		static AggregateOutput max(int col) {
			return new AggregateOutput(AGG_MAX, col);
		}

		static AggregateOutput avg(int col) {
			return new AggregateOutput(AGG_AVG, col);
		}

		/** Id-preserving MIN: keeps the winning id via {@code hooks.compareValues}; exact typed emission downstream. */
		static AggregateOutput minId(int col) {
			return new AggregateOutput(AGG_MIN_ID, col);
		}

		/** Id-preserving MAX: keeps the winning id via {@code hooks.compareValues}. */
		static AggregateOutput maxId(int col) {
			return new AggregateOutput(AGG_MAX_ID, col);
		}

		boolean isCountKind() {
			return kind == AGG_COUNT_STAR || kind == AGG_COUNT || kind == AGG_COUNT_DISTINCT;
		}

		boolean needsNumericHooks() {
			return kind == AGG_SUM || kind == AGG_MIN || kind == AGG_MAX || kind == AGG_AVG;
		}

		boolean needsHooks() {
			return needsNumericHooks() || kind == AGG_MIN_ID || kind == AGG_MAX_ID;
		}
	}

	/** HAVING guard over a count-kind aggregate output. */
	static final class Having {
		final int outputIndex;
		final int op;
		final long threshold;

		Having(int outputIndex, int op, long threshold) {
			this.outputIndex = outputIndex;
			this.op = op;
			this.threshold = threshold;
		}
	}

	/**
	 * Grouped or global aggregation terminal. Output rows are the group columns followed by the aggregate outputs. With
	 * no group columns exactly one row is produced, even over empty input (SPARQL global-aggregate semantics); with
	 * group columns, only observed groups produce rows.
	 */
	static final class Aggregate extends Terminal {
		final int[] groupCols;
		final AggregateOutput[] outputs;
		final Having having; // nullable

		Aggregate(int[] groupCols, AggregateOutput[] outputs, Having having, OutputMods mods) {
			super(mods);
			if (outputs.length == 0) {
				throw new IllegalArgumentException("aggregate needs at least one output");
			}
			if (having != null) {
				if (having.outputIndex < 0 || having.outputIndex >= outputs.length) {
					throw new IllegalArgumentException("HAVING references output " + having.outputIndex);
				}
				if (!outputs[having.outputIndex].isCountKind()) {
					throw new IllegalArgumentException("HAVING is only supported over count aggregates in this tier");
				}
			}
			this.groupCols = groupCols;
			this.outputs = outputs;
			this.having = having;
		}

		Aggregate having(int outputIndex, int op, long threshold) {
			return new Aggregate(groupCols, outputs, new Having(outputIndex, op, threshold), mods);
		}

		Aggregate withMods(OutputMods mods) {
			return new Aggregate(groupCols, outputs, having, mods);
		}

		@Override
		int stride() {
			return groupCols.length + outputs.length;
		}

		@Override
		void key(StringBuilder key) {
			key.append("agg(g=");
			for (int i = 0; i < groupCols.length; i++) {
				key.append(i == 0 ? "" : ",").append(groupCols[i]);
			}
			key.append(";o=");
			for (int i = 0; i < outputs.length; i++) {
				key.append(i == 0 ? "" : ",").append(outputs[i].kind).append(':').append(outputs[i].col);
			}
			if (having != null) {
				key.append(";h=")
						.append(having.outputIndex)
						.append(':')
						.append(having.op)
						.append(':')
						.append(having.threshold);
			}
			key.append(");");
			mods.key(key);
		}

		@Override
		void requirements(Requirements requirements) {
			for (AggregateOutput output : outputs) {
				if (output.needsHooks()) {
					requirements.hooks = true;
				}
			}
			if (mods.orderKeys != null && mods.valueOrder) {
				requirements.hooks = true;
			}
		}
	}

	// ------------------------------------------------------------------
	// Kernel root
	// ------------------------------------------------------------------

	static final class Kernel {
		final List<Node> pipeline;
		final int columnCount;
		final Terminal terminal;
		final Requirements requirements;
		private final String shapeKey;

		Kernel(int columnCount, List<Node> pipeline, Terminal terminal) {
			if (columnCount < 0 || columnCount > 64) {
				throw new IllegalArgumentException("column count out of range: " + columnCount);
			}
			this.pipeline = List.copyOf(pipeline);
			this.columnCount = columnCount;
			this.terminal = terminal;
			this.requirements = new Requirements();
			for (Node node : this.pipeline) {
				node.requirements(requirements);
			}
			terminal.requirements(requirements);
			validateColumns();
			StringBuilder key = new StringBuilder("ir1:cols=").append(columnCount).append(';');
			for (Node node : this.pipeline) {
				node.key(key);
			}
			terminal.key(key);
			this.shapeKey = key.toString();
		}

		private void validateColumns() {
			BitSet produced = new BitSet();
			for (Node node : pipeline) {
				node.produced(produced);
			}
			if (produced.length() > columnCount) {
				throw new IllegalArgumentException(
						"node writes column " + (produced.length() - 1) + " outside column count " + columnCount);
			}
			if (terminal instanceof Emit) {
				for (int col : ((Emit) terminal).cols) {
					checkColumn(col);
				}
			} else {
				Aggregate aggregate = (Aggregate) terminal;
				for (int col : aggregate.groupCols) {
					checkColumn(col);
				}
				for (AggregateOutput output : aggregate.outputs) {
					if (output.kind != AGG_COUNT_STAR) {
						checkColumn(output.col);
					}
				}
			}
			if (terminal.mods.orderKeys != null) {
				for (int key : terminal.mods.orderKeys) {
					if (key < 0 || key >= terminal.stride()) {
						throw new IllegalArgumentException("order key " + key + " outside output stride");
					}
				}
			}
		}

		private void checkColumn(int col) {
			if (col < 0 || col >= columnCount) {
				throw new IllegalArgumentException("column " + col + " outside column count " + columnCount);
			}
		}

		String shapeKey() {
			return shapeKey;
		}

		String className() {
			return "org.eclipse.rdf4j.sail.lmdb.gen.IrKernel_" + Long.toHexString(fnv(shapeKey));
		}

		int stride() {
			return terminal.stride();
		}

		private static long fnv(String text) {
			long hash = 0xCBF29CE484222325L;
			for (int i = 0; i < text.length(); i++) {
				hash ^= text.charAt(i);
				hash *= 0x100000001B3L;
			}
			return hash;
		}
	}
}
